export const isaInstructionByMnemonic: ReadonlyMap<string, IsaInstructionEntry> =
  new Map(isaInstructions.map((entry) => [entry.mnemonic, entry]));

/** Instructions available for a profile, sorted by mnemonic. */
export function isaMnemonicsForProfile(profile: CourseProfile): readonly string[] {
  return isaInstructions
    .filter((entry) => entry.profiles.includes(profile))
    .map((entry) => entry.mnemonic)
    .sort();
}

/** Tutorial-required instruction set for a profile, sorted by mnemonic. */
export function requiredMnemonicsForProfile(profile: CourseProfile): readonly string[] {
  return isaInstructions
    .filter((entry) => entry.layer === 'required' && entry.profiles.includes(profile))
    .map((entry) => entry.mnemonic)
    .sort();
}

/** Whether this instruction has one architectural delay slot in a profile. */
export function instructionHasDelaySlot(entry: IsaInstructionEntry, profile: CourseProfile): boolean {
  return entry.delaySlotProfiles.includes(profile);
}

/** Architectural exception kinds enabled for this instruction in a profile. */
export function instructionExceptionsForProfile(
  entry: IsaInstructionEntry,
  profile: CourseProfile
): readonly ExceptionKind[] {
  return entry.possibleExceptionsByProfile[profile] ?? [];
}
